"""Shipped-order reconciliation, 1 Mar to 31 May 2025 (UTC). Read-only against the order service.

Every good response is cached under RAW, so a rerun resumes without refetching.
"""
import datetime as dt
import decimal
import http.client
import json
import os
import re
import time
import urllib.error
import urllib.request
from collections import Counter

BASE = "http://localhost:8080"
RAW = "/tmp/recon/raw"
LOG_PATH = "/tmp/recon/fetch.log"
RESULT_PATH = "/tmp/recon/result.json"
MAX_FAILURES = 25  # per request, for failures other than 429
WINDOW_START = dt.datetime(2025, 3, 1, tzinfo=dt.timezone.utc)
WINDOW_END = dt.datetime(2025, 6, 1, tzinfo=dt.timezone.utc)  # exclusive: 31 May is the last included day
REGIONS = ("north", "south", "east", "west")

os.makedirs(RAW, exist_ok=True)
_log_file = open(LOG_PATH, "a", encoding="utf-8")
_token = None
_customers = {}


def log(msg):
    stamp = dt.datetime.now(dt.timezone.utc).strftime("%H:%M:%S")
    line = f"{stamp} {msg}"
    print(line, flush=True)
    _log_file.write(line + "\n")
    _log_file.flush()


def send(method, path, token=None):
    headers = {"Authorization": f"Bearer {token}"} if token else {}
    req = urllib.request.Request(BASE + path, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status, resp.headers, resp.read()
    except urllib.error.HTTPError as e:
        return e.code, e.headers, e.read()


def stated_wait(headers, body):
    """The wait the service asks for, in seconds, or None if it does not say."""
    value = headers.get("Retry-After")
    if value is not None:
        return float(value)
    try:
        data = json.loads(body)
    except ValueError:
        return None
    if isinstance(data, dict):
        for key in ("retry_after", "retry_after_seconds"):
            if key in data:
                return float(data[key])
    return None


def new_token():
    token = call("POST", "/token", authed=False)["token"]
    log("token acquired")
    return token


def call(method, path, authed=True, allow_404=False):
    """One API call, retried until it succeeds. Returns parsed JSON, or None for an allowed 404."""
    global _token
    failures = 0
    while True:
        if authed and _token is None:
            _token = new_token()
        try:
            status, headers, body = send(method, path, _token if authed else None)
        except (OSError, http.client.HTTPException) as e:
            status, headers, body = 0, {}, repr(e).encode()
        text = body[:300].decode("utf-8", "replace")
        if status == 200:
            try:
                return json.loads(body)
            except ValueError:
                status, text = 0, "non-JSON body: " + text
        if status == 429:
            wait = stated_wait(headers, body)
            if wait is None:
                raise RuntimeError(f"{path}: 429 without a stated wait: {text!r}")
            log(f"{path}: 429 {text!r}; waiting the stated {wait}s")
            time.sleep(wait + 0.5)
            continue
        if status == 404 and allow_404:
            log(f"{path}: 404 {text!r}")
            return None
        failures += 1
        if failures > MAX_FAILURES:
            raise RuntimeError(f"{path}: {failures - 1} failures, last status {status}: {text!r}")
        if status in (401, 403) and authed:
            log(f"{path}: {status} {text!r}; fetching a new token (failure {failures})")
            _token = new_token()
        elif status == 0 or status >= 500:
            log(f"{path}: status {status} {text!r} (failure {failures}); retrying")
            time.sleep(min(30, 2 ** failures))
        else:
            raise RuntimeError(f"{path}: unexpected status {status}: {text!r}")


def save_json(path, data):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2)
        f.write("\n")
    os.replace(tmp, path)


def load_orders():
    pages = {}
    number = 1
    while True:
        cache = f"{RAW}/orders_page_{number:03d}.json"
        if os.path.exists(cache):
            with open(cache, encoding="utf-8") as f:
                data = json.load(f)
        else:
            data = call("GET", f"/orders?page={number}")
            if data.get("page") != number:
                raise RuntimeError(f"asked for page {number}, got {data.get('page')!r}")
            save_json(cache, data)
        pages[number] = data
        log(f"page {number}/{data['total_pages']}: {len(data['items'])} items, next={data['next']!r}")
        if data["next"] is None:
            break
        if data["next"] != f"/orders?page={number + 1}":
            raise RuntimeError(f"page {number}: unexpected next link {data['next']!r}")
        number += 1
