    pages = load_orders()
    listing = [(number, order) for number in sorted(pages) for order in pages[number]["items"]]
    log(f"listing entries: {len(listing)} across {len(pages)} pages")
    log(f"status values seen: {dict(Counter(order['status'] for _, order in listing))}")

    first = {}     # order id -> first listing of that order
    repeats = []   # (page, order id, identical to first listing?)
    for number, order in listing:
        oid = order["id"]
        if oid in first:
            repeats.append((number, oid, order == first[oid]))
        else:
            first[oid] = order
    log(f"distinct orders: {len(first)}; repeated listings discarded: {len(repeats)}")
    log(f"repeated listings identical to the first listing: {sum(same for _, _, same in repeats)}")
    log(f"repeated listings by page: {dict(Counter(number for number, _, _ in repeats))}")

    numbers = sorted(int(oid.removeprefix("ord-")) for oid in first)
    missing = sorted(set(range(numbers[0], numbers[-1] + 1)) - set(numbers))
    log(f"id range ord-{numbers[0]:04d}..ord-{numbers[-1]:04d}; ids missing from that range: {missing}")

    offsets = Counter()
    qualifying = []
    excluded = Counter()
    for oid, order in first.items():
        placed = parse_utc(order["placed_at"])  # raises on a timestamp with no offset
        offsets[re.search(r"(Z|[+-]\d\d:?\d\d)$", order["placed_at"]).group(1)] += 1
        if not isinstance(order["amount_cents"], int) or order["amount_cents"] < 0:
            raise RuntimeError(f"{oid}: amount_cents {order['amount_cents']!r}")
        if order["status"] != "shipped":
            excluded[order["status"]] += 1
        elif not WINDOW_START <= placed < WINDOW_END:
            excluded["shipped, outside window"] += 1
        else:
            qualifying.append(order)
    log(f"offsets seen in placed_at: {dict(offsets)}")
    log(f"excluded: {dict(excluded)}; qualifying: {len(qualifying)}")

    by_region = {region: 0 for region in REGIONS}
    total = 0
    unresolved = []
    for order in qualifying:
        cust = customer(order["customer_id"])
        if cust.get("not_found") or cust.get("region") not in by_region:
            unresolved.append((order["id"], order["customer_id"], cust))
            continue
        pct = cust["discount_pct"]
        if not isinstance(pct, int) or not 0 <= pct <= 100:
            raise RuntimeError(f"{order['id']}: discount_pct {pct!r}")
        cents = discount_half_up(order["amount_cents"], pct)
        if cents != discount_decimal(order["amount_cents"], pct):
            raise RuntimeError(f"rounding methods disagree on {order['id']}")
        total += cents
        by_region[cust["region"]] += cents
    log(f"distinct customers looked up: {len(_customers)}")
    if unresolved:
        log(f"qualifying orders with unresolvable customers: {unresolved}")
        raise RuntimeError("totals not written: some customers could not be resolved")

    assert sum(by_region.values()) == total
    result = {
        "total_cents": total,
        "order_count": len(qualifying),
        "duplicates_skipped": len(repeats),
        "by_region": by_region,
    }
    save_json(RESULT_PATH, result)
    log(f"result: {json.dumps(result)}")


if __name__ == "__main__":
    main()

